{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket lacks explicit KMS encryption",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "The bucket has no Terraform-managed encryption configuration, so KMS-backed server-side encryption is not explicitly enforced."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted objects cannot be recovered, increasing the impact of accidental deletion or destructive activity."
    },
    {
      "check_id": "CKV_AWS_53,CKV_AWS_54,CKV_AWS_55,CKV_AWS_56",
      "title": "S3 public access protections are not enforced",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "Although the current ACL is private, no bucket-level public access block prevents future public ACLs or bucket policies from exposing data."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
  acl    = "private"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "b" {
  bucket = aws_s3_bucket.b.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "b" {
  bucket = aws_s3_bucket.b.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "b" {
  bucket = aws_s3_bucket.b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
",
  "fix_summary": "Added explicit KMS-backed server-side encryption, enabled object versioning, and enforced all four S3 bucket-level public access protections."
}
